const tsChart = (key, data, period, zoom, labelsOn, hoverIdx, unit, dec, self) => {
  const n = period === '3개월' ? 3 : period === '12개월' ? 12 : 6;
  let rows = data.slice(data.length - n);
  if (zoom) rows = rows.slice(zoom[0], zoom[1] + 1);
  const vals = rows.map((r) => r[1]);
  const min = Math.min.apply(null, vals), max = Math.max.apply(null, vals);
  const lo = Math.max(0, min - (max - min) * 0.35 - 0.5), hi = max + (max - min) * 0.12 + 0.5;
  const m = rows.length;
  const X = (i) => m === 1 ? 100 : (i / (m - 1)) * 200;
  const Y = (v) => 100 - (v - lo) / (hi - lo) * 100;
  const line = rows.map((r, i) => X(i).toFixed(1) + ',' + Y(r[1]).toFixed(1)).join(' ');
  const area = 'M' + rows.map((r, i) => X(i).toFixed(1) + ',' + Y(r[1]).toFixed(1)).join(' L') + ' L200,100 L0,100 Z';
  const prev = (i) => i > 0 ? rows[i - 1][1] : null;
  return {
    line, area, unit,
    axis: [0, 1, 2, 3, 4].map((k) => ({ t: (lo + (hi - lo) * (4 - k) / 4).toFixed(dec) })),
    cols: rows.map((r, i) => {
      const p = prev(i);
      const delta = p === null ? '' : (r[1] - p >= 0 ? '▲ +' : '▼ ') + (r[1] - p).toFixed(dec) + unit;
      return {
        label: r[0], value: labelsOn ? r[1].toFixed(dec) : '',
        tip: r[0] + '  ·  ' + r[1].toFixed(dec) + ' ' + unit + (p === null ? '' : '\n전월 대비 ' + delta),
        dotTop: Y(r[1]).toFixed(1) + '%',
        over: () => { const st = {}; st[key + 'Hover'] = i; if (self.state[key + 'Drag'] !== null && self.state[key + 'Drag'] !== i) { st[key + 'Zoom'] = [Math.min(self.state[key + 'Drag'], i), Math.max(self.state[key + 'Drag'], i)]; } self.setState(st); },
        down: () => { const st = {}; st[key + 'Drag'] = i; self.setState(st); },
        up: () => { const st = {}; st[key + 'Drag'] = null; self.setState(st); }
      };
    }),
    readout: hoverIdx !== null && rows[hoverIdx] ? rows[hoverIdx][1].toFixed(dec) + ' ' + unit : '',
    readoutSub: hoverIdx !== null && rows[hoverIdx]
      ? rows[hoverIdx][0] + (hoverIdx > 0 ? ' · 전월 대비 ' + ((rows[hoverIdx][1] - rows[hoverIdx - 1][1]) >= 0 ? '▲ +' : '▼ ') + (rows[hoverIdx][1] - rows[hoverIdx - 1][1]).toFixed(dec) + unit : '')
      : '차트에 마우스를 올리면 값이 표시됩니다'
  };
};
