      + (s.polHover && s.polHover.axis === axis ? 'box-shadow:0 6px 18px ' + shadow + ';' : '');

    const tourBtn = (off) => 'font-size:12.5px;font-weight:700;padding:8px 14px;border-radius:3px;white-space:nowrap;transition:background-color 400ms ease-out,color 400ms ease-out;'
      + (off ? 'background:#F1F3F5;color:#BDC2C8;cursor:default;pointer-events:none;' : 'background:' + NAVY + ';color:#fff;cursor:pointer;');

